//! @file
//! @brief Histogram bucket generator utilities for configuring OpenTelemetry histogram views.
//!
//! Provides bucket generator functions that return pre-configured bucket boundaries for common
//! histogram use cases. Use these generators to configure OpenTelemetry SDK Views before creating
//! histogram instruments; instruments created before a view is registered won't have that view's
//! configuration applied.
//!
//! Available generators:
//! - extendedLatencyBucketGenerator() - For latency/duration measurements (most common)
//! - gRPCLatencyBucketGenerator() - For gRPC call latencies (standard gRPC spec)
//! - gRPCSizeBucketGenerator() - For message/payload size measurements
//! - gRPCCountBucketGenerator() - For count-based measurements
//! - linearBucketGenerator() - Configurable linear bucket spacing
//! - linearBucketGeneratorFixedBucketCount() - Linear spacing with fixed bucket count
//! - exponentialBucketGenerator() - Configurable exponential bucket spacing
//!
//! @note Views must be configured before instruments are created. See docs/observability/Metrics.md
//!       for usage examples.

#pragma once

#include <carb/Assert.h>
#include <cfloat>
#include <cmath>
#include <limits>
#include <vector>

namespace omni::observability
{

//! @brief Generates linear bucket boundaries with configurable start, end, and step.
//!
//! Creates evenly spaced bucket boundaries starting at @p start and incrementing by @p step
//! until reaching @p end. Boundaries are strictly increasing as required by OpenTelemetry.
//!
//! @param start The first bucket boundary (must be less than end).
//! @param end The maximum bucket boundary.
//! @param step The increment between consecutive buckets (must be positive).
//! @return Vector of bucket boundaries, or empty vector if parameters are invalid.
inline std::vector<double> linearBucketGenerator(double start, double end, double step)
{
    std::vector<double> sequence;

    // OpenTelemetry requires strictly increasing bucket boundaries
    CARB_ASSERT(step > 0);
    CARB_ASSERT(start < end);

    if (step <= 0 || start >= end)
    {
        return sequence;
    }

    for (double value = start; value <= end; value += step)
    {
        sequence.push_back(value);
    }

    return sequence;
}

//! @brief Generates linear bucket boundaries with a fixed number of buckets.
//!
//! Divides the range [start, end] into a specified number of equally-sized buckets.
//! Unlike linearBucketGenerator(), this excludes the range minimum from the output.
//! Boundaries are strictly increasing as required by OpenTelemetry.
//!
//! @param start The first value in the range (must be less than end).
//! @param end The last value in the range.
//! @param num_buckets The number of buckets to generate (must be greater than zero).
//! @return Vector of bucket boundaries, or empty vector if parameters are invalid.
inline std::vector<double> linearBucketGeneratorFixedBucketCount(double start, double end, size_t num_buckets)
{
    std::vector<double> sequence;

    // OpenTelemetry requires strictly increasing bucket boundaries
    CARB_ASSERT(num_buckets > 0);
    CARB_ASSERT(start < end);

    if (num_buckets == 0 || start >= end)
    {
        return sequence;
    }

    double step = (end - start) / static_cast<double>(num_buckets);

    for (double value = start + step; value <= end; value += step)
    {
        sequence.push_back(value);
    }

    return sequence;
}

//! @brief Generates exponential bucket boundaries with configurable start, end, and factor.
//!
//! Creates exponentially spaced bucket boundaries starting at @p start and multiplying by @p factor
//! until reaching @p end. Ideal for values spanning multiple orders of magnitude.
//! Boundaries are strictly increasing as required by OpenTelemetry.
//!
//! @param start The first bucket boundary (must be positive and less than end).
//! @param end The maximum bucket boundary.
//! @param factor The multiplication factor between buckets (must be greater than 1).
//! @return Vector of bucket boundaries, or empty vector if parameters are invalid.
inline std::vector<double> exponentialBucketGenerator(double start, double end, double factor)
{
    std::vector<double> sequence;

    // OpenTelemetry requires strictly increasing bucket boundaries.
    // Use DBL_MIN to reject denormalized values that could cause floating point precision issues.
    constexpr double kMinStart = DBL_MIN;
    CARB_ASSERT(std::isfinite(start));
    CARB_ASSERT(std::isfinite(end));
    CARB_ASSERT(factor > 1);
    CARB_ASSERT(start >= kMinStart);
    CARB_ASSERT(start < end);

    if (factor <= 1 || !std::isfinite(start) || start < kMinStart || !std::isfinite(end) || start >= end)
    {
        return sequence;
    }

    double prevValue = 0;
    double value = start;
    while (value <= end)
    {
        sequence.push_back(value);
        prevValue = value;
        value *= factor;

        // Prevent infinite loop if floating-point precision limits are reached
        if (value <= prevValue * (1 + std::numeric_limits<double>::epsilon()))
        {
            break;
        }
    }

    return sequence;
}

//! @brief Generates bucket boundaries optimized for latency and duration measurements.
//!
//! Returns 40 pre-configured bucket boundaries designed for measuring latencies and durations
//! in seconds. Recommended for most latency use cases.
//!
//! Range: 0.1ms to 1000s (~16 minutes) with finer granularity for typical request latencies.
//! Based on gRPC recommendations with extended upper range.
//!
//! @return Vector of 40 bucket boundaries in seconds: {0, 0.0001, 0.0005, 0.001, ..., 1000}
//! @see https://github.com/grpc/proposal/blob/master/A66-otel-stats.md#units
inline std::vector<double> extendedLatencyBucketGenerator()
{
    std::vector<double> boundaries = { 0,    0.0001, 0.0005, 0.001, 0.002, 0.003, 0.004, 0.005, 0.006, 0.008,
                                       0.01, 0.013,  0.016,  0.02,  0.025, 0.03,  0.04,  0.05,  0.065, 0.08,
                                       0.1,  0.13,   0.16,   0.2,   0.25,  0.3,   0.4,   0.5,   0.65,  0.8,
                                       1,    2,      5,      10,    20,    50,    100,   300,   600,   1000 };
    return boundaries;
}

//! @brief Generates bucket boundaries optimized for message and payload size measurements.
//!
//! Returns 14 pre-configured bucket boundaries designed for measuring message sizes, payload
//! sizes, or other byte-based metrics. Based on gRPC recommendations.
//!
//! Range: 0 bytes to 4GB with exponential distribution.
//!
//! @return Vector of 14 bucket boundaries in bytes: {0, 1024, 2048, ..., 4294967296}
//! @see https://github.com/grpc/proposal/blob/master/A66-otel-stats.md#units
inline std::vector<double> gRPCSizeBucketGenerator()
{
    std::vector<double> boundaries = { 0,       1024,    2048,     4096,     16384,     65536,      262144,
                                       1048576, 4194304, 16777216, 67108864, 268435456, 1073741824, 4294967296 };
    return boundaries;
}

//! @brief Generates bucket boundaries optimized for gRPC latency measurements.
//!
//! Returns 41 pre-configured bucket boundaries designed for measuring gRPC call latencies
//! in seconds. Based on gRPC OpenTelemetry recommendations.
//!
//! Range: 0ms to 100s with finer granularity for typical RPC latencies.
//!
//! @return Vector of 41 bucket boundaries in seconds: {0, 0.00001, 0.00005, 0.0001, ..., 100}
//! @see https://github.com/grpc/proposal/blob/master/A66-otel-stats.md#units
inline std::vector<double> gRPCLatencyBucketGenerator()
{
    std::vector<double> boundaries = { 0,     0.00001, 0.00005, 0.0001, 0.0003, 0.0006, 0.0008, 0.001, 0.002,
                                       0.003, 0.004,   0.005,   0.006,  0.008,  0.01,   0.013,  0.016, 0.02,
                                       0.025, 0.03,    0.04,    0.05,   0.065,  0.08,   0.1,    0.13,  0.16,
                                       0.2,   0.25,    0.3,     0.4,    0.5,    0.65,   0.8,    1,     2,
                                       5,     10,      20,      50,     100 };
    return boundaries;
}

//! @brief Generates bucket boundaries optimized for count measurements.
//!
//! Returns 18 pre-configured bucket boundaries designed for measuring counts, such as
//! message counts, retry counts, or other discrete quantities. Based on gRPC recommendations.
//!
//! Range: 0 to 65536 with exponential distribution (powers of 2).
//!
//! @return Vector of 18 bucket boundaries: {0, 1, 2, 4, 8, ..., 65536}
//! @see https://github.com/grpc/proposal/blob/master/A66-otel-stats.md#units
inline std::vector<double> gRPCCountBucketGenerator()
{
    std::vector<double> boundaries = { 0,   1,   2,    4,    8,    16,   32,    64,    128,
                                       256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536 };
    return boundaries;
}

} // namespace omni::observability
